import math, sys
sys.path.insert(0, 'tools')
from fit_mag_sphere import load_samples
pts = load_samples('docs/evidence/measurements/mag-tilt-109samples.json')

def kasa_normal(P):
    M = [[0.0]*4 for _ in range(4)]
    for x,y,z in P:
        v = [x, y, z, 1.0]
        for i in range(4):
            for j in range(4):
                M[i][j] += v[i]*v[j]
    return M

def eigvals_sym(A):
    # Jacobi eigenvalue iteration for small symmetric matrix
    n = len(A); a = [row[:] for row in A]
    for _ in range(200):
        p, q, mx = 0, 1, 0.0
        for i in range(n):
            for j in range(i+1, n):
                if abs(a[i][j]) > mx: mx, p, q = abs(a[i][j]), i, j
        if mx < 1e-12: break
        app, aqq, apq = a[p][p], a[q][q], a[p][q]
        theta = 0.5*math.atan2(2*apq, aqq-app)
        c, s = math.cos(theta), math.sin(theta)
        for k in range(n):
            akp, akq = a[k][p], a[k][q]
            a[k][p], a[k][q] = c*akp - s*akq, s*akp + c*akq
        for k in range(n):
            apk, aqk = a[p][k], a[q][k]
            a[p][k], a[q][k] = c*apk - s*aqk, s*apk + c*aqk
    return sorted(a[i][i] for i in range(n))

mx = sum(p[0] for p in pts)/len(pts); my = sum(p[1] for p in pts)/len(pts); mz = sum(p[2] for p in pts)/len(pts)
for tag, P in [('raw       ', pts), ('centroided', [(x-mx, y-my, z-mz) for x,y,z in pts])]:
    ev = eigvals_sym(kasa_normal(P))
    print(f'Kasa normal-matrix eigenvalues {tag}: min={ev[0]:.3e} max={ev[-1]:.3e}  cond ≈ {ev[-1]/max(ev[0],1e-30):.2e}')
